package December20;

public class char_datatype {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char ch = 'a';
		
		int ch1 = ch + 1;
		char ch2 = (char)ch1; // typecasting
		System.out.println(ch); // a
		System.out.println(ch1);// 98
		System.out.println(ch2);

	}

}
